def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 1.0))

    prev_bids = []
    strong_opponents = 0
    desperate_opponents = 0
    richest_budget = 0.0

    for opp in alive_opponents:
        if opp.get('budget', 0) > richest_budget:
            richest_budget = opp.get('budget', 0)
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opponents += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            strong_opponents += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if no_water >= 2:
        urgency = 3

    if urgency == 3:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif urgency == 2:
        if highest_prev >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * 0.88
        else:
            bid = max(DAILY_SALARY * 0.72, highest_prev + 2.0)
    elif urgency == 1:
        if highest_prev >= DAILY_SALARY * 1.8:
            bid = DAILY_SALARY * (0.28 + 0.10 * scarcity)
        else:
            bid = max(DAILY_SALARY * (0.42 + 0.10 * scarcity), avg_prev * 0.55)
    else:
        if highest_prev >= DAILY_SALARY * 1.5:
            bid = DAILY_SALARY * (0.10 + 0.10 * scarcity)
        elif highest_prev > 0:
            bid = max(DAILY_SALARY * (0.22 + 0.08 * scarcity), highest_prev * 0.45)
        else:
            bid = DAILY_SALARY * (0.18 + 0.08 * scarcity)

    if len(alive_opponents) == 1:
        only_opp = alive_opponents[int(0)]
        opp_prev = only_opp.get('previous_trace', {})
        opp_prev_bid = opp_prev.get('bid') if opp_prev else None
        if urgency <= 1 and opp_prev_bid is not None and opp_prev_bid > DAILY_SALARY * 1.5:
            bid = min(bid, DAILY_SALARY * (0.12 + 0.10 * scarcity))
        if urgency >= 2 and opp_prev_bid is not None and only_opp.get('budget', 0) < budget:
            bid = max(bid, min(budget, opp_prev_bid * 0.75))

    if desperate_opponents >= 2 and urgency >= 1:
        bid = max(bid, DAILY_SALARY * 0.78)

    reserve_days = 3 if hp > 4 else 2
    reserve = reserve_days * DAILY_SALARY
    if budget < reserve:
        bid = min(bid, max(0.0, budget - DAILY_SALARY * 0.5))

    if day >= 8:
        if urgency >= 2:
            bid = max(bid, DAILY_SALARY * 0.9)
        else:
            bid = max(bid, DAILY_SALARY * 0.35)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, bid enough to cover our need safely.
    if not alive_opps:
        need_bid = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, need_bid)

    # Read yesterday's immediate behavior from previous_trace.
    prev_bids = []
    prev_max = 0.0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
                prev_bids.append(b)
                if b > prev_max:
                    prev_max = b
            except Exception:
                pass

    # Estimate how much water we need to avoid falling behind.
    # Supply is total available; we bid to compete for enough to keep hp stable.
    # Risk increases with no_water_days.
    risk = 0.0
    if no_water_days >= 2:
        risk = 0.35
    elif no_water_days == 1:
        risk = 0.15

    # If Cindy-like pressure existed yesterday (high max), don't match her ceiling; bid a competitive mid-high.
    # Use thresholds relative to DAILY_SALARY.
    pressure = 0.0
    if prev_max >= DAILY_SALARY * 1.8:
        pressure = 0.9
    elif prev_max >= DAILY_SALARY * 1.3:
        pressure = 0.7
    elif prev_max >= DAILY_SALARY * 0.9:
        pressure = 0.5
    else:
        pressure = 0.35

    # Supply factor: when supply is low, competition is tighter; increase bid slightly.
    supply_factor = 0.0
    if supply <= float(MIN_SUPPLY):
        supply_factor = 0.25
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.05
    else:
        # linear between MIN_SUPPLY and MAX_SUPPLY
        t = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        supply_factor = 0.25 * (1.0 - t) + 0.05 * t

    # Base bid depends on hp: if healthy, we can bid less; if low, bid more.
    if hp >= 8:
        base = DAILY_SALARY * (0.45 + supply_factor + risk)
    elif hp >= 5:
        base = DAILY_SALARY * (0.65 + supply_factor + risk)
    else:
        base = DAILY_SALARY * (0.85 + supply_factor + risk)

    # Adjust for observed pressure.
    target = base + pressure * (DAILY_SALARY * 0.25)

    # Never exceed a conservative fraction of budget; also ensure non-negative.
    # If budget is small, cap harder.
    if budget <= DAILY_SALARY:
        cap = budget
    else:
        cap = min(budget, DAILY_SALARY * 2.0)

    # Final bid rounding to 2 decimals.
    bid = min(target, cap)
    if bid < 0.0:
        bid = 0.0

    return float(round(bid, 2))

